use super::*;
use crate::cn::wps::moss::filefmt::biff8::util::CellRangeAddress::CellRangeAddress;
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let n=["NullPointerException","IllegalArgumentException","RuntimeException","StringIndexOutOfBoundsException","NumberFormatException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":n})}}}
fn sheet(p:&Value)->Value{let s=p["sheet"].as_str();let w=p["book"].as_str();let mut a="prefix:".to_string();let mut b=a.clone();let needs=call(||SheetNameFormatter::needsDelimiting(s));let one=call(||SheetNameFormatter::appendFormat(&mut a,s));let two=call(||SheetNameFormatter::appendFormat__workbook(&mut b,w,s));json!({"needs":needs,"one":one,"oneOut":a,"two":two,"twoOut":b})}
fn range(v:&Value)->Option<CellRangeAddress>{if v.is_null(){None}else{Some(CellRangeAddress::new(v[0].as_i64().unwrap()as i32,v[1].as_i64().unwrap()as i32,v[2].as_i64().unwrap()as i32,v[3].as_i64().unwrap()as i32))}}
fn reference(p:&Value)->CellReference{if p.get("text").is_some(){return CellReference::fromString(p["text"].as_str().expect("NullPointerException")).unwrap_or_else(|e|panic!("{e}"));}let r=p["row"].as_i64().unwrap()as i32;let c=p["col"].as_i64().unwrap()as i32;if p["short"]==true{return CellReference::CellReference__short(r,c as i16);}if p["two"]==true{return CellReference::CellReference(r,c);}CellReference::CellReference__sheet(p["sheet"].as_str().map(str::to_string),r,c,p["ra"].as_bool().unwrap(),p["ca"].as_bool().unwrap())}
fn cell(p:&Value)->Value{let mut c=None;let mut out=json!({"construct":call(||{c=Some(reference(p));})});let Some(x)=c else{return out;};out["row"]=json!(x.getRow());out["col"]=json!(x.getCol());out["sheet"]=json!(x.getSheetName());out["ra"]=json!(x.isRowAbsolute());out["ca"]=json!(x.isColAbsolute());out["format"]=call(||x.formatAsString());out["string"]=call(||x.toString());out["parts"]=json!(x.getCellRefParts());out["hash"]=json!(x.hashCode());out["selfEquals"]=json!(x.equals(Some(&x)));out["nullEquals"]=json!(x.equals__object(None));out["objectEquals"]=json!(x.equals__object(Some(&123i32)));out["rc"]=json!(p["addresses"].as_array().unwrap().iter().map(|a|{let f=range(&a["formula"]);let o=range(&a["origin"]);call(||x.formatAsRCString(f.as_ref().map(|a|&a.base),o.as_ref().map(|a|&a.base)))}).collect::<Vec<_>>());out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]
fn original_android_sheet_and_reference_formatting(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/reference-format-r0b53");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut sheets=json!({});for sv in[SpreadsheetVersion::EXCEL97,SpreadsheetVersion::EXCEL2007]{*crate::org::apache::poi::ss::SpreadsheetVersion::CUR_VERSION.lock().unwrap()=sv;sheets[if sv==SpreadsheetVersion::EXCEL97{"EXCEL97"}else{"EXCEL2007"}]=json!(input["sheets"].as_array().unwrap().iter().map(sheet).collect::<Vec<_>>());}let eq=(0..8).map(|a|(0..8).map(|b|CellReference::CellReference__sheet(if a<4{None}else{Some("other".into())},4,5,a&2!=0,a&1!=0).equals(Some(&CellReference::CellReference__sheet(if b<4{None}else{Some("other".into())},4,5,b&2!=0,b&1!=0)))).collect::<Vec<_>>()).collect::<Vec<_>>();let actual=json!({"numeric":(0..65536).map(|c|Character::getNumericValue(c as u16)).collect::<Vec<_>>(),"special":(0..65536).map(|c|call(||SheetNameFormatter::isSpecialChar(c as u16))).collect::<Vec<_>>(),"sheets":sheets,"cells":input["cells"].as_array().unwrap().iter().map(cell).collect::<Vec<_>>(),"cols":input["cols"].as_array().unwrap().iter().map(|s|call(||CellReference::convertColStringToIndex(s.as_str().expect("NullPointerException")).unwrap_or_else(|e|panic!("{e}")))).collect::<Vec<_>>(),"equals":eq});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");assert!(CellReference::isPartAbsolute(Some("$A")));assert!(!CellReference::isPartAbsolute(Some("A")));}
